import json
from pathlib import Path
P=Path(__file__).parent;rows=[]
links={x['href'].split('/')[-1]:x['href'] for x in json.loads((P/'cms-links.json').read_text()) if '.pdf' in x['href']}
def file(comp,y,sol=False):
 candidates=([f'{'j' if comp=='CJMO' else ''}{'sol' if sol else 'exam'}{y}.pdf'] if y<=2020 else [f'{comp}{y}-{'solutions' if sol else 'problems'}.pdf',f'{y}{comp}_{'solutions' if sol else 'exam'}_en.pdf',f'{y}{comp}_{'solutions' if sol else 'exam'}_en-1.pdf',f'{comp.lower()}{y}-solutions-en.pdf',f'{y}{comp}-exam-en.pdf',f'{comp}-{y}-questions-en-4.pdf',f'{comp}-{y}-questions-en.pdf'])
 for x in candidates:
  if x in links:return links[x]
 raise ValueError((comp,y,sol,candidates))
def q(comp,y,n,t,s,tags,reason,shared=None):
 x=dict(comp=comp,y=y,n=n,topic=t,statement=s,tags=tags.split('|'),reason=reason,source=file(comp,y),solutionUrl=file(comp,y,True))
 if shared:x['appearances']=[dict(country='Canada',competition='CJMO',year=y,number=str(shared),sourceUrl=file('CJMO',y))]
 rows.append(x)
u='CMO';j='CJMO'
q(u,2015,5,'Number Theory',r'Let $p$ and $(p-1)/2$ be primes, and let $a,b,c$ be integers not divisible by $p$. Prove that at most $1+\sqrt{2p}$ integers $n$ with $1\le n<p$ satisfy $p\mid a^n+b^n+c^n$.','Modular arithmetic|Primes|Counting','The safe-prime hypothesis restricts multiplicative orders. Comparing pairs of successful exponents and bounding repeated differences is needed to obtain the square-root bound.')
q(u,2016,4,'Combinatorics',r'Fix integers $A<B<2A$. A flea starts at $0$ and jumps right by $A$ or $B$. An adversary marks finitely many disjoint blocks of $A$ consecutive positive integers as lava, leaving at least $F$ unmarked integers between blocks and marking none below $F$. Prove that the least $F$ guaranteeing a path avoiding all lava, regardless of the blocks, is $(n-1)A+B$, where $n$ is determined by $A/(n+1)\le B-A<A/n$.','Algorithms & constructions|Games & strategies|Modular arithmetic','The exact threshold requires a global reachability description across many separated barriers and a matching adversarial obstruction; greedy local jumps alone do not prove either direction.')
q(u,2016,5,'Geometry',r'In acute triangle $ABC$, altitudes $AD,BE$ meet at $H$, and $M$ is the midpoint of $AB$. Circles $(DEM)$ and $(ABH)$ intersect at $P,Q$, with $P$ on the same side of $CH$ as $A$. Prove that $ED,PH,MQ$ meet at one point on the circumcircle of $ABC$.','Circles & tangency|Triangle centres|Concurrency & collinearity','The two claimed incidences must identify the same point on the original circumcircle. Auxiliary circle and ratio relations, with the P/Q branch correctly chosen, make this a demanding geometry argument.')
q(u,2017,1,'Algebra',r'For pairwise distinct nonnegative real numbers $a,b,c$, prove $\dfrac{a^2}{(b-c)^2}+\dfrac{b^2}{(c-a)^2}+\dfrac{c^2}{(a-b)^2}>2$.','Inequalities|Algebraic identities','Ordering the variables and comparing the two larger terms gives a short strict bound; the nonnegative endpoint and pairwise-distinct assumptions must be retained.')
q(u,2018,4,'Algebra',r'Find every real polynomial $p$ for which a real polynomial $q$ exists such that $p(1)+\cdots+p(n)=p(n)q(n)$ for all positive integers $n$.','Polynomials|Sums & products|Algebraic identities','Degree comparison forces q to be linear, but repeated root propagation is then needed to classify p. The telescoping converse imposes an additional discrete restriction on its shift.')
q(u,2018,5,'Number Theory',r'Fix an even positive integer $k$. Start with any integer $N>1$ and repeatedly choose a prime divisor $p$ of the current value, replacing $N$ by $N(p^k-p^{-1})$. Prove that infinitely many such $k$ force the current value eventually to be divisible by $2018$, regardless of all choices.','Primes|Modular arithmetic|Invariants','A special family of exponents controls the multiplicative orders of newly introduced primes. The key decreasing quantity discards selected prime factors rather than tracking N itself.')
q(u,2019,5,'Combinatorics',r'Two players alternately add a previously absent edge between $n\ge3$ fixed planar points, with no three collinear. The player first completing an odd cycle loses; crossings are not vertices. Determine for which $n$ the first player has a winning strategy.','Games & strategies|Graph theory|Parity','Avoiding odd cycles means maintaining bipartite components, but the winning strategy must control their eventual partitions and the parity of remaining safe edges.')
q(u,2020,5,'Combinatorics',r'Among $19998$ people, every group of $9999$ contains at least $9999$ mutual-friend pairs. Determine the least possible total number of friend pairs.','Graph theory|Extremal arguments|Counting','An averaging edge bound is not by itself sharp enough. The proof needs a structural extremal analysis of half-sized vertex subsets and a matching graph construction.')
q(j,2020,1,'Algebra',r'A positive sequence satisfies $a_1=1$ and $a_{n+1}^2+a_{n+1}=a_n$ for $n\ge1$. Prove $a_n\ge1/n$ for every $n$.','Sequences & recurrences|Induction|Inequalities','Use the increasing function t²+t to carry the lower bound from n to n+1; the comparison at1/(n+1) is an elementary rational inequality.')
q(u,2021,1,'Geometry',r'An isosceles trapezoid $ABCD$ has $AB\parallel CD$, $AB>CD$ and $AD=BC$. Let $I$ be the centre of the circle tangent to lines $AB,AC,BD$ with $I,A$ on opposite sides of $BD$. Let $J$ similarly be the centre of the circle tangent to $CD,AC,BD$ with $J,D$ on opposite sides of $AC$. Prove $IC=JB$.','Similarity & congruence|Triangle centres|Transformations','The isosceles trapezoid gives a common symmetry axis; identifying the appropriate excentral angle bisectors makes the two required distances correspond.',shared=3)
q(u,2021,5,'Combinatorics',r'Nina and Tadashi alternate moves on a triple of nonnegative integers $(a,b,c)$ initially summing to $2021$, with Nina first. A move chooses an integer $k>0$, adds $k$ to one coordinate and subtracts $k$ from the other two. A player loses on making a coordinate negative. Count the ordered initial triples for which Tadashi can force a win.','Games & strategies|Invariants|Counting','The losing positions require a precise classification under unequal step sizes, followed by a count on the fixed-sum plane. Simple parity alone does not distinguish them.')
q(j,2021,1,'Geometry',r'Concentric circles $C_1,C_2$ have $C_1$ inside $C_2$. Distinct nondiametrically opposite points $P_1,P_2$ lie on $C_1$. Ray $P_1P_2$ meets $C_2$ at $Q_2$. The tangents to $C_1$ at $P_1$ and to $C_2$ at $Q_2$ meet at $X$; the other tangent from $X$ to $C_2$ touches at $Q_1$. Prove that $P_1X$ bisects $\angle Q_1P_1Q_2$.','Circles & tangency|Transformations|Angle chasing','The common centre makes the two tangent lengths from P1-related lines symmetric, and a short tangent-angle argument identifies the required bisector.')
q(u,2022,5,'Geometry',r'A convex pentagon has all five vertices on one circle and all five sides tangent to another circle inside it. Prove that the incentres of its ten vertex-triangles lie on two concentric circles.','Triangle centres|Circles & tangency|Trigonometry','The bicentric pentagon imposes strong but hidden relations between its arcs. One must separate two classes of triangles and show that their incentres have a common centre of rotation.')
q(j,2022,1,'Geometry',r'In an acute triangle $ABC$ with circumcircle $\Gamma$, the altitude lines from $A,B$ meet $\Gamma$ again at $D,E$. Prove that $AB=DE$ implies $\angle ACB=60^\circ$.','Circles & tangency|Angle chasing|Trigonometry','Equal chords convert the length condition into an arc relation; the altitude angles and acuteness eliminate the extraneous angle possibilities.')
q(j,2022,2,'Combinatorics',r'For which positive integers $n$ can an $n\times n$ board be tiled by T-shaped tetrominoes, each consisting of three unit squares in a row and a fourth attached to the middle square? Rotations are permitted.','Tilings & coverings|Colouring|Parity','Area divisibility gives n even, but a checkerboard parity obstruction strengthens the restriction. A small repeating tile block proves sufficiency.')
q(u,2023,4,'Number Theory',r'Let $f$ be a nonconstant integer-coefficient polynomial with $f(1)\ne1$. Call $m>0$ admissible if the set $\{f(d):d\mid m,\ d>0\}$ is exactly the positive divisor set of some positive integer. Prove that only finitely many $m$ are admissible.','Polynomials|Divisibility & GCD|Extremal arguments','The image must contain1 while also being closed under complementary divisors. Combining this with polynomial growth and divisibility restricts the original divisor set.')
q(u,2023,5,'Combinatorics',r'A simple graph on $n$ vertices has at most $kn$ edges across every partition of its vertices into two parts, where $k$ is a fixed positive integer. Find the largest guaranteed size of an independent vertex set, in terms of $n,k$.','Graph theory|Extremal arguments|Algorithms & constructions','The maximum-cut hypothesis must be converted into a sharp independent-set guarantee; a basic average-degree bound loses information, and the extremal examples matter.')
q(j,2023,1,'Number Theory',r'Let $s_1=a,s_2=b$ for nonnegative integers $a,b$, and set $s_{i+1}=|s_i-s_{i-1}|$ for $i\ge2$. Prove that some term is zero.','Sequences & recurrences|Infinite descent|Divisibility & GCD','The maximum of adjacent terms does not decrease every step, but decreases after a short block unless a zero occurs. This supplies the finite descent.')
q(j,2023,2,'Geometry',r'In right triangle $ABC$, $\angle C=90^\circ$, and $CD\perp AB$. The bisector of $\angle ACD$ meets $AD$ at $E$, and $EF\perp BC$ with $F\in BC$. Prove that the circle $(BEF)$ contains the midpoint of $CE$.','Circles & tangency|Similarity & congruence|Triangle geometry','The circle has diameter BE; the angle-bisector relation translates into the right angle needed at the midpoint of CE through a short similarity argument.')
q(u,2024,5,'Geometry',r'Three noncollinear points $A,B,C$ are marked. Allowed operations are: mark an arbitrary point, or one on a drawn line; join two marked points; mark the intersection of nonparallel drawn lines; and draw either parallel at distance1 from a drawn line. Prove that these operations suffice to construct the orthocentre of $ABC$.','Constructions & loci|Coordinates & vectors|Triangle centres','A fixed-width ruler does not directly supply perpendiculars or arbitrary distances. The construction must synthesize enough affine and metric operations to recover the altitudes.')
q(j,2024,1,'Combinatorics',r'An unknown cell of a $2\times4$ grid contains treasure. Each detector tests whether the cell lies in one specified rectangular subgrid. All detectors must be chosen in advance and run simultaneously. Find the least number guaranteeing the exact cell can be determined.','Logic & information|Algorithms & constructions|Counting','Binary information gives the lower bound; the rectangular restriction means a matching family of tests still needs to be constructed explicitly.')
q(j,2024,2,'Combinatorics',r'Put $I_n=\sum_{i=1}^{n}\sum_{j=1}^{n}\sum_{k=1}^{n}\min\{1/i,1/j,1/k\}$ and $H_n=\sum_{i=1}^{n}1/i$. Find $I_n-H_n$ as a formula in $n$.','Counting|Sums & products','Group triples by their maximum index: the corresponding count is r³−(r−1)³. Dividing by r leaves a polynomial sum and exactly the harmonic term that cancels.')
q(u,2025,1,'Combinatorics',r'$n$ people stand in a circle, each initially pointing to the person on their left. In each round, every person updates once, in any order: someone pointing to $b$ changes to the person whom $b$ currently points to. After $n$ rounds, prove that all point to the same person.','Graph theory|Invariants|Algorithms & constructions','Updates occur asynchronously, so ordinary repeated squaring does not apply. A monotone description of the directed cycle and the trees feeding it must give a uniform n-round bound.',shared=3)
q(u,2025,4,'Geometry',r'Let $ABC$ have circumcircle $\Gamma$ and $AB\ne AC$. Points $D,E$ on the arc $BC$ opposite $A$ satisfy $\angle BAE=\angle DAC$. Let $X,Y$ be the incentres of $BAE,CAD$, and let $Z$ be the intersection of the common external tangents of their incircles. Prove that $Z$ lies on the common chord-line of $\Gamma$ and $(AXY)$.','Circles & tangency|Triangle centres|Power of a point','The external homothety centre of two incircles must be located on a radical axis. The equal-angle condition is used to relate tangent ratios to the powers in two different circles.')
q(u,2025,5,'Combinatorics',r'A rectangle is partitioned into finitely many axis-parallel smaller rectangles, with no three sharing a common corner. An ant starts at the lower-left corner. At each move it chooses a small rectangle having its current position as a corner and travels to an adjacent corner of that rectangle. Prove that any route ending at the upper-right corner chooses some small rectangle on at least two moves.','Graph theory|Invariants|Combinatorial geometry','The local corner moves have a global planar obstruction. A useful invariant must distinguish opposite outer corners while remaining compatible with the non-grid subdivision.')
q(j,2025,1,'Number Theory',r'An infinite nonconstant arithmetic progression of integers contains $1$. Prove that it contains infinitely many integer cubes.','Modular arithmetic|Algorithms & constructions','Taking integers congruent to1 modulo the common difference produces cubes in the same residue class; choosing them far enough along the correct direction handles the progression’s starting point.')
q(u,2026,5,'Algebra',r'For each positive integer $n$, find the greatest $c_n$ for which there exist a degree-$n$ rational-coefficient polynomial $f$, an irrational real $a$, and $c_n$ distinct rationals $a_i$ such that every $f(a+a_i)$ is rational.','Polynomials|Rational numbers|Linear algebra','Rational values at translated rational inputs force constraints on the irrational coefficients of f(x+a). The upper bound must be matched by a polynomial construction at an algebraic irrational shift.')
q(j,2026,1,'Number Theory',r'Distinct positive integers $a,b,c$ have sum $29$. Find the smallest possible $a^2+b^2+c^2$.','Inequalities|Extremal arguments','Balancing decreases the sum of squares; distinctness prevents the unconstrained closest-to-equal triple, leaving a short comparison of adjacent integer candidates.')
q(j,2026,2,'Geometry',r'Trapezoid $ABCD$ has $AB\parallel CD$. Rhombi $BCWX$ and $ADYZ$ are erected with interiors disjoint from one another and from the trapezoid. Prove that the distance between the rhombus centres is at most half the perimeter of $ABCD$.','Geometric inequalities|Coordinates & vectors|Quadrilaterals & polygons','Join the rhombus centres through side midpoints. Half-diagonal bounds and the trapezoid midsegment turn the triangle inequality directly into the half-perimeter bound.')
